40: export async function plan(objective, directory, {
41:   apiKey = process.env.OPENROUTER_API_KEY,
42:   fetchImpl = fetch,
43: } = {}) {
44:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
45:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
46:   const investigate = await repositoryTools(directory);
47:   const output = join(directory, '.tag');
48:   try {
49:     await mkdir(output, { mode: 0o700 });
50:   } catch (error) {
51:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
52:     throw error;
53:   }
54:   let saving = false;
55:   try {
56:     const { data } = await request('/models', {}, fetchImpl);
57:     const model = data?.find(item => item.id === MODEL);
58:     const promptPrice = Number(model?.pricing?.prompt);
59:     const completionPrice = Number(model?.pricing?.completion);
60:     // Deliberately conservative caps, not a general-purpose cost reservation system.
61:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
62:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
63:       || Number(model.pricing.request ?? 0) !== 0) {
64:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
65:     }
66:     const messages = [
67:       { role: 'system', content: instructions },
68:       { role: 'user', content: objective },
69:     ];
70:     const investigation = [];
71:     let costUsd = 0;
72:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
73:       const body = {
74:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
75:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
76:         temperature: 0.2,
77:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
78:       };
79:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
80:         throw new Error('Research context limit reached. No graph saved; human review required.');
81:       }
82:       const response = await request('/chat/completions', {
83:         method: 'POST',
84:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
85:         body: JSON.stringify(body),
86:       }, fetchImpl);
87:       const cost = response.usage?.cost;
88:       costUsd = costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0 ? costUsd + cost : null;
89:       const choice = response.choices?.[0];
90:       const message = choice?.message;
91:       if (!message || choice.finish_reason === 'length' || response.error) {
92:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
93:       }
94:       if (message.tool_calls?.length) {
95:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
96:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
97:         for (const call of message.tool_calls) {
98:           let args;
99:           let result;
100:           try {
101:             args = JSON.parse(call.function.arguments);
102:             result = await investigate(call.function.name, args);
103:           } catch {
104:             // Do not return raw filesystem errors or other environment details to the model.
105:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
106:           }
107:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
108:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
109:         }
110:         continue;
111:       }
112:       if (!investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result))) {
113:         throw new Error('The model proposed a graph without reading repository evidence.');
114:       }
115:       let graph;
116:       try {
117:         graph = validateGraph(JSON.parse(message.content), objective);
118:       } catch (error) {
119:         throw new Error(`Invalid planner graph: ${error.message}. No repair or retry was made.`);
120:       }
121:       graph.run = { model: MODEL, createdAt: new Date().toISOString(), requests: turn, costUsd, investigation };
122:       const html = renderGraph(graph);
123:       saving = true;
124:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
125:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
126:       return join(output, 'graph.html');
127:     }
128:     throw new Error('Investigation limit reached. No graph saved.');
129:   } finally {
130:     if (!saving) await rm(output, { recursive: true });
131:   }
132: }
